const riskStyles = {
  Low: 'border-success/20 bg-success/10 text-success',
  Medium: 'border-warning/20 bg-warning/10 text-warning',
  High: 'border-danger/20 bg-danger/10 text-danger',
}

function RiskBadge({ risk }: { risk: string }) {
  return <Badge variant="outline" className={riskStyles[risk as keyof typeof riskStyles]}>{risk} risk</Badge>
}

function StatCard({ icon: Icon, label, value, detail, tone = 'teal' }: { icon: typeof Users; label: string; value: string; detail: string; tone?: string }) {
  return (
    <Card className="border-border/70 bg-card/85 shadow-sm transition-transform hover:-translate-y-0.5">
      <CardContent className="flex items-start justify-between p-5">
        <div className="flex flex-col gap-3">
          <p className="text-xs font-medium uppercase tracking-[0.14em] text-muted-foreground">{label}</p>
          <p className="font-mono text-3xl font-semibold tracking-tight">{value}</p>
          <p className="text-xs text-muted-foreground">{detail}</p>
        </div>
        <div className={`flex size-10 items-center justify-center rounded-xl bg-${tone}/10 text-${tone}`}><Icon /></div>
      </CardContent>
    </Card>
  )
}

export default function APAPPSDashboard({ userRole = 'admin', userId }: { userRole?: 'student' | 'admin' | 'lecturer'; userId?: string }) {
  const [active, setActive] = useState('Overview')
  const [studentMode, setStudentMode] = useState(userRole === 'student')
  const [query, setQuery] = useState('')
  const [riskFilter, setRiskFilter] = useState('All')
  const [selected, setSelected] = useState<typeof students[number] | null>(null)
  const [notes, setNotes] = useState<string[]>(['Discussed attendance recovery plan and paired student with a peer study group.'])
  const [note, setNote] = useState('')
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [liveCounts, setLiveCounts] = useState({ students: 0, lecturers: 0, unread: 0 })
  const [dataError, setDataError] = useState('')
  const [profile, setProfile] = useState<{ full_name: string | null; avatar_path: string | null; department: string | null }>({ full_name: null, avatar_path: null, department: null })
  const supabase = createClient()

  useEffect(() => {
    if (!supabase) return
    supabase.from('profiles').select('full_name, avatar_path, department').eq('id', userId).maybeSingle().then(({ data }) => { if (data) setProfile(data) })
    Promise.all([
      supabase.from('profiles').select('role', { count: 'exact', head: false }),
      supabase.from('notifications').select('id', { count: 'exact', head: true }).is('read_at', null),
    ]).then(([profilesResult, unreadResult]) => {
      if (profilesResult.error) { setDataError('Live data is unavailable. Check your Supabase RLS policies.') ; return }
      const rows = profilesResult.data ?? []
      setLiveCounts({ students: rows.filter((row) => row.role === 'student').length, lecturers: rows.filter((row) => row.role === 'lecturer').length, unread: unreadResult.count ?? 0 })
    })
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [userRole])

  const filteredStudents = useMemo(() => students.filter((student) => {
    const matchesQuery = `${student.name} ${student.id} ${student.course}`.toLowerCase().includes(query.toLowerCase())
    const matchesRisk = riskFilter === 'All' || student.risk === riskFilter
    return matchesQuery && matchesRisk
  }), [query, riskFilter])

  function addNote() {
    if (!note.trim()) return
    setNotes((current) => [note.trim(), ...current])
    setNote('')
  }

  const navItems = [
    { label: 'Overview', icon: LayoutDashboard },
    { label: userRole === 'lecturer' ? 'My Cohort' : 'Students', icon: Users },
    { label: 'Analytics', icon: BarChart3 },
    { label: 'Academic records', icon: ClipboardPlus },
    { label: 'Timetable', icon: CalendarDays },
    { label: 'Interventions', icon: MessageSquareText },
    { label: 'Notifications', icon: Bell },
    { label: 'Settings', icon: Settings },
  ]

  return (
    <div className="min-h-screen bg-background text-foreground">
      <div className="flex min-h-screen">
        <aside className={`${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} fixed inset-y-0 left-0 z-20 flex w-72 flex-col border-r border-sidebar-border bg-sidebar px-5 py-6 transition-transform lg:static lg:translate-x-0`}>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-2xl bg-primary text-primary-foreground shadow-lg shadow-primary/20"><ShieldCheck /></div><div><p className="font-mono text-lg font-semibold tracking-tight">APAPPS</p><p className="text-[10px] uppercase tracking-[0.18em] text-muted-foreground">Academic intelligence</p></div></div>
            <Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setSidebarOpen(false)} aria-label="Close menu"><X /></Button>
          </div>
          <div className="mt-10 flex flex-col gap-2">
            <p className="px-3 pb-2 text-[10px] font-medium uppercase tracking-[0.18em] text-muted-foreground">Workspace</p>
            {navItems.map(({ label, icon: Icon }) => <Button key={label} variant={active === label ? 'secondary' : 'ghost'} className="justify-start gap-3 rounded-xl px-3" onClick={() => { setActive(label); setSidebarOpen(false) }}><Icon data-icon="inline-start" />{label}{label === 'Students' && <Badge variant="secondary" className="ml-auto">8</Badge>}</Button>)}
          </div>
          <div className="mt-auto flex flex-col gap-4">
            <Card className="border-primary/15 bg-primary/5"><CardContent className="flex flex-col gap-3 p-4"><Sparkles className="text-primary" /><p className="text-sm font-medium">Prediction engine online</p><p className="text-xs leading-5 text-muted-foreground">Risk scores refresh after every academic record update.</p><Badge variant="outline" className="w-fit border-success/20 bg-success/10 text-success">● Live model</Badge></CardContent></Card>
            <div className="flex items-center gap-3 rounded-xl border border-sidebar-border p-3"><div className="flex size-9 items-center justify-center rounded-full bg-accent font-semibold text-accent-foreground">JO</div><div className="min-w-0"><p className="truncate text-sm font-medium">Dr. James Osei</p><p className="truncate text-xs text-muted-foreground">Lecturer · CS Dept.</p></div><MoreHorizontal className="ml-auto text-muted-foreground" /></div>
          </div>
        </aside>
        <main className="min-w-0 flex-1">
          <header className="sticky top-0 z-10 flex h-20 items-center justify-between border-b border-border/70 bg-background/90 px-5 backdrop-blur-xl lg:px-10">
            <div className="flex items-center gap-3"><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setSidebarOpen(true)} aria-label="Open menu"><Menu /></Button><div><p className="text-xs font-medium uppercase tracking-[0.16em] text-primary">{studentMode ? 'Student portal' : 'Lecturer workspace'}</p><h1 className="text-xl font-semibold tracking-tight">{studentMode ? `Welcome back, ${profile.full_name?.split(' ')[0] || 'Student'}` : active}</h1></div></div>
            <div className="flex items-center gap-2"><Button variant="outline" size="sm" className="hidden gap-2 rounded-xl sm:flex" onClick={() => setStudentMode((mode) => !mode)}><UserRound />{studentMode ? 'Lecturer view' : 'Student view'}</Button><Button variant="ghost" size="icon" aria-label="Notifications" onClick={() => { setActive('Notifications'); setStudentMode(true) }}><Bell /></Button><button type="button" aria-label="Open profile settings" onClick={() => { setActive('Settings'); setStudentMode(true) }} className="flex size-9 items-center justify-center overflow-hidden rounded-full bg-accent text-sm font-semibold text-accent-foreground">{profile.avatar_path ? <img src={`/api/profile-photo?pathname=${encodeURIComponent(profile.avatar_path)}`} alt="Profile" className="size-full object-cover" /> : (profile.full_name?.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase() || 'ST')}</button></div>
          </header>

          {studentMode ? <StudentView active={active} userId={userId} /> : userRole === 'lecturer' ? <LecturerView active={active} userId={userId} /> : active === 'Students' ? <LiveDirectory counts={liveCounts} error={dataError} /> : active !== 'Overview' ? <FunctionalWorkspacePanel active={active} userId={userId} /> : <div className="mx-auto flex max-w-[1500px] flex-col gap-8 p-5 lg:p-10">
            <section className="flex flex-col justify-between gap-5 rounded-3xl border border-primary/15 bg-gradient-to-br from-primary/10 via-card to-card p-6 shadow-sm lg:flex-row lg:items-end lg:p-8"><div className="flex max-w-2xl flex-col gap-3"><div className="flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-primary"><Activity /> Monday, 18 August 2026</div><h2 className="max-w-xl text-pretty text-3xl font-semibold tracking-tight lg:text-5xl">See who needs support, before they fall behind.</h2><p className="max-w-xl text-sm leading-6 text-muted-foreground lg:text-base">APAPPS turns academic signals into clear next steps for every student in your classroom.</p></div><Button className="w-fit rounded-xl" onClick={() => setActive('Students')}><ClipboardPlus data-icon="inline-start" />Review students<ArrowUpRight data-icon="inline-end" /></Button></section>
            <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard icon={Users} label={userRole === 'lecturer' ? 'My cohort' : 'Total students'} value="128" detail="Across 4 active courses" /><StatCard icon={AlertTriangle} label="Need attention" value="19" detail="4 fewer than last month" tone="warning" /><StatCard icon={TrendingUp} label="Avg. performance" value="74.8%" detail="↑ 6.2% this semester" tone="primary" /><StatCard icon={Target} label="Success score" value="78.4%" detail="Weighted academic health" tone="accent" /><StatCard icon={ClipboardPlus} label="Records updated" value="86%" detail="This week across courses" tone="teal" /></section><section className="grid gap-6 lg:grid-cols-3"><Card><CardHeader><CardTitle>Signal coverage</CardTitle><CardDescription>Inputs used by the prediction engine</CardDescription></CardHeader><CardContent className="flex flex-col gap-4">{[['Attendance', 86], ['Assignments', 74], ['Classwork', 81], ['Examinations', 68]].map(([label, value]) => <div key={label as string} className="flex flex-col gap-2"><div className="flex justify-between text-sm"><span>{label}</span><span className="font-mono text-muted-foreground">{value}%</span></div><Progress value={value as number} /></div>)}</CardContent></Card><Card><CardHeader><CardTitle>AI intervention queue</CardTitle><CardDescription>Assistive recommendations to review</CardDescription></CardHeader><CardContent className="flex flex-col gap-3"><Badge variant="outline" className="w-fit border-warning/20 bg-warning/10 text-warning">7 high priority</Badge><p className="text-sm leading-6 text-muted-foreground">Recommendations combine attendance, assessment momentum, engagement, and course-level performance. A lecturer always makes the final decision.</p><Button variant="outline" className="rounded-xl" onClick={() => setActive('Interventions')}>Review recommendations <ChevronRight data-icon="inline-end" /></Button></CardContent></Card><Card><CardHeader><CardTitle>Data quality</CardTitle><CardDescription>Keep your predictions trustworthy</CardDescription></CardHeader><CardContent className="flex flex-col gap-3"><div className="flex items-center justify-between"><span className="text-sm">Records with all signals</span><span className="font-mono text-success">72%</span></div><Progress value={72} /><p className="text-xs leading-5 text-muted-foreground">Add attendance, classwork, assignments, and examination results to improve coverage.</p><Button variant="outline" className="rounded-xl" onClick={() => setActive('Academic records')}>Enter records <ClipboardPlus data-icon="inline-start" /></Button></CardContent></Card></section>
            <section className="grid gap-6 xl:grid-cols-[1.45fr_0.9fr]"><Card className="min-w-0"><CardHeader className="flex flex-row items-start justify-between gap-4"><div><CardTitle>Performance pulse</CardTitle><CardDescription>Class average across the current semester</CardDescription></div><Badge variant="outline" className="border-success/20 bg-success/10 text-success">+6.2% trend</Badge></CardHeader><CardContent><div className="h-64 w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData} margin={{ left: -15, right: 5, top: 10 }}><defs><linearGradient id="scoreFill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="var(--chart-1)" stopOpacity={0.28} /><stop offset="95%" stopColor="var(--chart-1)" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="4 4" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><YAxis domain={[50, 100]} axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><Tooltip contentStyle={{ background: 'var(--popover)', border: '1px solid var(--border)', borderRadius: 12, color: 'var(--popover-foreground)' }} /><Area type="monotone" dataKey="score" stroke="var(--chart-1)" strokeWidth={3} fill="url(#scoreFill)" /></AreaChart></ResponsiveContainer></div></CardContent></Card>
            <Card><CardHeader><CardTitle>Risk overview</CardTitle><CardDescription>Current prediction distribution</CardDescription></CardHeader><CardContent><div className="relative h-48"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={riskData} dataKey="value" nameKey="name" innerRadius={58} outerRadius={78} paddingAngle={4} stroke="none">{riskData.map((entry) => <Cell key={entry.name} fill={entry.color} />)}</Pie><Tooltip contentStyle={{ background: 'var(--popover)', border: '1px solid var(--border)', borderRadius: 12 }} /></PieChart></ResponsiveContainer><div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center"><span className="font-mono text-2xl font-semibold">128</span><span className="text-xs text-muted-foreground">students</span></div></div><div className="flex flex-col gap-3">{riskData.map((item) => <div key={item.name} className="flex items-center justify-between text-sm"><span className="flex items-center gap-2"><span className="size-2 rounded-full" style={{ backgroundColor: item.color }} />{item.name}</span><span className="font-mono text-muted-foreground">{item.value}%</span></div>)}</div></CardContent></Card></section>
            <section className="grid gap-6 xl:grid-cols-[1.45fr_0.9fr]"><Card className="min-w-0"><CardHeader className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><CardTitle>Students requiring attention</CardTitle><CardDescription>Prioritized by the APAPPS prediction engine</CardDescription></div><Button variant="ghost" size="sm" onClick={() => setActive('Students')}>View all <ChevronRight data-icon="inline-end" /></Button></CardHeader><CardContent className="flex flex-col gap-4"><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search students..." className="rounded-xl pl-9" /></div><select value={riskFilter} onChange={(event) => setRiskFilter(event.target.value)} aria-label="Filter by risk" className="h-10 rounded-xl border border-input bg-background px-3 text-sm"><option>All</option><option>High</option><option>Medium</option><option>Low</option></select></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-sm"><thead><tr className="border-b text-left text-xs uppercase tracking-wider text-muted-foreground"><th className="pb-3 font-medium">Student</th><th className="pb-3 font-medium">Course</th><th className="pb-3 font-medium">Attendance</th><th className="pb-3 font-medium">Avg. score</th><th className="pb-3 font-medium">Risk</th><th className="pb-3" /></tr></thead><tbody>{filteredStudents.slice(0, 5).map((student) => <tr key={student.id} className="border-b border-border/60 last:border-0"><td className="py-4"><button className="flex items-center gap-3 text-left" onClick={() => setSelected(student)}><span className="flex size-9 items-center justify-center rounded-full bg-accent text-xs font-semibold text-accent-foreground">{student.initials}</span><span><span className="block font-medium">{student.name}</span><span className="block text-xs text-muted-foreground">{student.id}</span></span></button></td><td className="py-4 text-muted-foreground">{student.course}</td><td className="py-4 font-mono">{student.attendance}%</td><td className="py-4 font-mono">{Math.round((student.ca + student.exam) / 2)}%</td><td className="py-4"><RiskBadge risk={student.risk} /></td><td className="py-4 text-right"><Button variant="ghost" size="icon" aria-label={`Open ${student.name}`} onClick={() => setSelected(student)}><ChevronRight /></Button></td></tr>)}</tbody></table></div></CardContent></Card>
            <Card><CardHeader><CardTitle>Recent interventions</CardTitle><CardDescription>Small actions, meaningful momentum</CardDescription></CardHeader><CardContent className="flex flex-col gap-5">{['Amara Okafor', 'Kemi Adeyemi', 'Daniel Mensah'].map((name, index) => <div key={name} className="flex gap-3"><div className="mt-1 flex size-7 shrink-0 items-center justify-center rounded-full bg-success/10 text-success"><CheckCircle2 /></div><div className="min-w-0"><p className="text-sm font-medium">{index === 0 ? 'Study group assigned' : index === 1 ? 'Advisor meeting logged' : 'Attendance plan created'}</p><p className="truncate text-xs text-muted-foreground">{name} · {index + 1}d ago</p></div></div>)}<Separator /><Button variant="outline" className="rounded-xl" onClick={() => setSelected(students[0])}><MessageSquareText data-icon="inline-start" />Log an intervention</Button></CardContent></Card></section>
          </div>}
        </main>
      </div>
      {selected && <div className="fixed inset-0 z-30 flex items-end justify-center bg-foreground/30 p-0 backdrop-blur-sm sm:items-center sm:p-6" onClick={() => setSelected(null)}><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-t-3xl border border-border bg-card p-6 shadow-2xl sm:rounded-3xl" onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between gap-4"><div className="flex items-center gap-3"><div className="flex size-12 items-center justify-center rounded-2xl bg-accent font-semibold text-accent-foreground">{selected.initials}</div><div><p className="text-xl font-semibold">{selected.name}</p><p className="text-sm text-muted-foreground">{selected.id} · {selected.course}</p></div></div><Button variant="ghost" size="icon" onClick={() => setSelected(null)} aria-label="Close student details"><X /></Button></div><div className="mt-6 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-muted/60 p-4"><p className="text-xs text-muted-foreground">Attendance</p><p className="mt-1 font-mono text-2xl font-semibold">{selected.attendance}%</p></div><div className="rounded-2xl bg-muted/60 p-4"><p className="text-xs text-muted-foreground">CA score</p><p className="mt-1 font-mono text-2xl font-semibold">{selected.ca}%</p></div><div className="rounded-2xl bg-muted/60 p-4"><p className="text-xs text-muted-foreground">Prediction</p><div className="mt-2"><RiskBadge risk={selected.risk} /></div></div></div><div className="mt-6 flex flex-col gap-3"><div className="flex items-center justify-between"><div><p className="font-semibold">Performance trend</p><p className="text-xs text-muted-foreground">Last six assessment checkpoints</p></div><TrendingUp className="text-primary" /></div><div className="h-44"><ResponsiveContainer width="100%" height="100%"><AreaChart data={selected.trend.map((score, index) => ({ period: `P${index + 1}`, score }))}><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="4 4" /><XAxis dataKey="period" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><YAxis domain={[30, 100]} axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><Area type="monotone" dataKey="score" stroke="var(--chart-1)" fill="var(--chart-1)" fillOpacity={0.12} strokeWidth={3} /></AreaChart></ResponsiveContainer></div></div><div className="mt-4 rounded-2xl border border-warning/20 bg-warning/5 p-4"><p className="flex items-center gap-2 text-sm font-medium text-warning"><Sparkles /> Prediction explanation</p><p className="mt-2 text-sm leading-6 text-muted-foreground">{selected.risk === 'High' ? 'Low attendance and declining CA scores are the strongest contributing factors.' : selected.risk === 'Medium' ? 'Recent assessment performance is flattening. A check-in could protect momentum.' : 'Consistent attendance and improving assessment scores suggest a healthy trajectory.'}</p></div><div className="mt-6 flex flex-col gap-3"><p className="font-semibold">Intervention notes</p>{notes.map((item, index) => <div key={`${item}-${index}`} className="rounded-xl bg-muted/60 p-3 text-sm text-muted-foreground">{item}</div>)}<div className="flex gap-2"><Input value={note} onChange={(event) => setNote(event.target.value)} placeholder="Add a note about the next step..." onKeyDown={(event) => { if (event.key === 'Enter' && !event.nativeEvent.isComposing && event.keyCode !== 229) addNote() }} /><Button onClick={addNote} aria-label="Add intervention note"><Plus /></Button></div></div></div></div>}
    </div>
  )
}

function LiveDirectory({ counts, error }: { counts: { students: number; lecturers: number; unread: number }; error: string }) {
  const [people, setPeople] = useState<Array<{ id: string; full_name: string; role: string; department: string | null; verification_status: string | null }>>([])
  const [search, setSearch] = useState('')
  const supabase = createClient()
  useEffect(() => { if (supabase) supabase.from('profiles').select('id, full_name, role, department, verification_status').order('full_name').then(({ data }) => setPeople(data ?? [])) }, [supabase])
  const filtered = people.filter((person) => `${person.full_name} ${person.department ?? ''} ${person.role}`.toLowerCase().includes(search.toLowerCase()))
  return <div className="mx-auto flex max-w-[1500px] flex-col gap-6 p-5 lg:p-10"><section className="rounded-3xl border border-primary/15 bg-primary/5 p-6"><p className="text-xs uppercase tracking-[0.18em] text-primary">Live institution directory</p><h2 className="mt-2 text-3xl font-semibold">Students and lecturers</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">This workspace reads directly from Supabase. Search records, review verification status, and open profiles for editing.</p></section>{error && <p className="rounded-xl border border-danger/20 bg-danger/10 p-3 text-sm text-danger">{error}</p>}<section className="grid gap-4 sm:grid-cols-3"><StatCard icon={Users} label="Students" value={String(counts.students)} detail="Live profile count" /><StatCard icon={GraduationCap} label="Lecturers" value={String(counts.lecturers)} detail="Live profile count" tone="primary" /><StatCard icon={Bell} label="Unread notifications" value={String(counts.unread)} detail="Across your account" tone="warning" /></section><Card><CardHeader><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle>People directory</CardTitle><CardDescription>Use the database values, not demo rows.</CardDescription></div><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search name, department, role..." className="max-w-sm rounded-xl" /></div></CardHeader><CardContent><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead><tr className="border-b text-left text-xs uppercase tracking-wider text-muted-foreground"><th className="pb-3">Name</th><th className="pb-3">Role</th><th className="pb-3">Department</th><th className="pb-3">Status</th></tr></thead><tbody>{filtered.map((person) => <tr key={person.id} className="border-b border-border/60"><td className="py-4 font-medium">{person.full_name || 'Unnamed profile'}</td><td className="py-4 capitalize">{person.role}</td><td className="py-4 text-muted-foreground">{person.department || 'Not provided'}</td><td className="py-4"><Badge variant="outline">{person.role === 'lecturer' ? person.verification_status || 'pending' : 'active'}</Badge></td></tr>)}</tbody></table>{people.length === 0 && <p className="py-10 text-center text-sm text-muted-foreground">No live profiles found yet. Create a confirmed account through the signup flow.</p>}</div></CardContent></Card></div>
}

function FunctionalWorkspacePanel({ active, userId }: { active: string; userId?: string }) {
  const supabase = createClient()
  const [studentId, setStudentId] = useState('')
  const [courseCode, setCourseCode] = useState('')
  const [courseTitle, setCourseTitle] = useState('')
  const [attendance, setAttendance] = useState('')
  const [classwork, setClasswork] = useState('')
  const [assignmentScore, setAssignmentScore] = useState('')
  const [examScore, setExamScore] = useState('')
  const [message, setMessage] = useState('')
  async function saveRecord() {
    if (!supabase || !studentId || !courseCode) return setMessage('Student ID and course code are required.')
    const { error } = await supabase.from('academic_records').insert({ student_id: studentId, lecturer_id: userId, course_code: courseCode, attendance: Number(attendance), classwork: Number(classwork), assignments: Number(assignmentScore), examinations: Number(examScore), term: 'First semester' })
    setMessage(error ? error.message : 'Academic record saved to Supabase.')
    if (!error) { setStudentId(''); setCourseCode(''); setCourseTitle(''); setAttendance(''); setClasswork(''); setAssignmentScore(''); setExamScore('') }
  }
  const [title, setTitle] = useState('')
  const [body, setBody] = useState('')
  const [venue, setVenue] = useState('')
  const [day, setDay] = useState('Monday')
  async function saveWorkflowItem() {
    if (!supabase || !userId || !title.trim()) return setMessage('Title and signed-in user are required.')
    const table = active === 'Timetable' ? 'timetables' : active === 'Interventions' ? 'interventions' : 'notifications'
    const payload = active === 'Timetable' ? { title: title.trim(), course_code: courseCode.trim(), day_of_week: day, venue: venue.trim(), created_by: userId } : active === 'Interventions' ? { student_id: studentId, created_by: userId, type: 'academic', title: title.trim(), rationale: body.trim(), status: 'open' } : { user_id: studentId || userId, title: title.trim(), body: body.trim(), kind: 'announcement' }
    const { error } = await supabase.from(table).insert(payload)
    setMessage(error ? error.message : `${active} saved to Supabase.`)
    if (!error) { setTitle(''); setBody(''); setVenue('') }
  }
  if (active === 'Timetable' || active === 'Interventions' || active === 'Notifications') return <LiveStudentPanel title={`${active} workspace`} description="Create and publish records to the live Supabase database. Empty states are real; no demo rows are shown." loading={false}><div className="grid gap-4 sm:grid-cols-2"><Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder={active === 'Timetable' ? 'Class title' : active === 'Interventions' ? 'Intervention title' : 'Notification title'} /><Input value={studentId} onChange={(e) => setStudentId(e.target.value)} placeholder={active === 'Timetable' ? 'Student/course audience ID (optional)' : 'Student profile ID (optional)'} />{active === 'Timetable' && <><Input value={courseCode} onChange={(e) => setCourseCode(e.target.value)} placeholder="Course code" /><Input value={venue} onChange={(e) => setVenue(e.target.value)} placeholder="Venue" /><select value={day} onChange={(e) => setDay(e.target.value)} className="h-10 rounded-xl border border-input bg-background px-3 text-sm"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option></select></>}{active !== 'Timetable' && <Input value={body} onChange={(e) => setBody(e.target.value)} placeholder={active === 'Interventions' ? 'Reason and recommended action' : 'Notification message'} />}</div><Button onClick={saveWorkflowItem} className="w-fit rounded-xl">Save {active.toLowerCase()}</Button>{message && <p className="text-sm text-muted-foreground">{message}</p>}</LiveStudentPanel>
  if (active === 'Academic records') return <div className="mx-auto flex max-w-6xl flex-col gap-6 p-5 lg:p-10"><section className="rounded-3xl border border-primary/15 bg-primary/5 p-6"><p className="text-xs uppercase tracking-[0.18em] text-primary">Live lecturer workspace</p><h2 className="mt-2 text-3xl font-semibold">Academic record entry</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Enter verified student performance data. The record is written directly to Supabase and becomes visible to the student.</p></section><Card><CardContent className="grid gap-4 p-6 sm:grid-cols-2"><Input value={studentId} onChange={(e) => setStudentId(e.target.value)} placeholder="Student profile ID" /><Input value={courseCode} onChange={(e) => setCourseCode(e.target.value)} placeholder="Course code" /><Input value={courseTitle} onChange={(e) => setCourseTitle(e.target.value)} placeholder="Course title" /><Input type="number" value={attendance} onChange={(e) => setAttendance(e.target.value)} placeholder="Attendance %" /><Input type="number" value={classwork} onChange={(e) => setClasswork(e.target.value)} placeholder="Classwork %" /><Input type="number" value={assignmentScore} onChange={(e) => setAssignmentScore(e.target.value)} placeholder="Assignment %" /><Input type="number" value={examScore} onChange={(e) => setExamScore(e.target.value)} placeholder="Exam %" /><Button onClick={saveRecord} className="rounded-xl sm:col-span-2">Save academic record</Button>{message && <p className="text-sm text-muted-foreground sm:col-span-2">{message}</p>}</CardContent></Card></div>
  return <WorkspacePanel active={active} />
}

function WorkspacePanel({ active }: { active: string }) {
  const [csvName, setCsvName] = useState('')
  const [saved, setSaved] = useState(false)
  const title = active === 'Academic records' ? 'Academic records' : active === 'Interventions' ? 'Intervention studio' : active === 'Timetable' ? 'University timetable' : active
  return <div className="mx-auto flex max-w-[1500px] flex-col gap-6 p-5 lg:p-10"><section className="flex flex-col gap-3 rounded-3xl border border-primary/15 bg-primary/5 p-6"><p className="text-xs font-medium uppercase tracking-[0.18em] text-primary">{active === 'Academic records' ? 'Lecturer data workspace' : 'Workspace view'}</p><h2 className="text-3xl font-semibold tracking-tight">{title}</h2><p className="max-w-2xl text-sm leading-6 text-muted-foreground">{active === 'Academic records' ? 'Capture attendance, classwork, assignments, and examinations manually or import a validated CSV file.' : active === 'Interventions' ? 'Review transparent AI-assisted recommendations, record the action taken, and monitor outcomes.' : active === 'Timetable' ? 'Publish weekly class schedules so students always know what is next, where it happens, and who is teaching.' : 'Explore the signals and students connected to your APAPPS workspace.'}</p></section>{active === 'Academic records' ? <div className="grid gap-6 lg:grid-cols-2"><Card><CardHeader><CardTitle>Manual record entry</CardTitle><CardDescription>One academic record per student and course.</CardDescription></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><Input placeholder="Student matric number" /><Input placeholder="Course code" /><Input type="number" placeholder="Attendance %" /><Input type="number" placeholder="Assignments %" /><Input type="number" placeholder="Classwork %" /><Input type="number" placeholder="Examination %" /><Button className="rounded-xl sm:col-span-2" onClick={() => setSaved(true)}>{saved ? 'Record saved' : 'Save academic record'}</Button></CardContent></Card><Card><CardHeader><CardTitle>CSV import</CardTitle><CardDescription>Expected columns: matric_number, course_code, attendance, assignments, classwork, examinations.</CardDescription></CardHeader><CardContent className="flex flex-col gap-4"><Input type="file" accept=".csv,text/csv" onChange={(event) => setCsvName(event.target.files?.[0]?.name ?? '')} />{csvName && <p className="text-sm text-muted-foreground">Ready to preview {csvName}</p>}<Button variant="outline" className="rounded-xl" disabled={!csvName} onClick={() => setSaved(true)}>Validate and preview import</Button>{saved && <Badge variant="outline" className="w-fit border-success/20 bg-success/10 text-success">Validation complete · 0 blocking errors</Badge>}</CardContent></Card></div> : active === 'Timetable' ? <div className="grid gap-6 lg:grid-cols-3"><Card className="lg:col-span-2"><CardHeader><CardTitle>Weekly schedule</CardTitle><CardDescription>Students see published classes matched to their programme and level.</CardDescription></CardHeader><CardContent className="flex flex-col gap-3">{[['Monday','09:00','CSC 301','Algorithms','LT 2'],['Tuesday','11:00','MTH 204','Discrete Mathematics','Room 12'],['Wednesday','10:00','CSC 305','Database Systems','Lab 1'],['Thursday','13:00','GST 202','Entrepreneurship','Hall B'],['Friday','08:00','CSC 307','Software Engineering','LT 4']].map(([day,time,code,name,venue]) => <div key={day} className="flex flex-col gap-2 rounded-2xl border border-border/70 bg-card/60 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-primary/10 text-primary"><CalendarDays /></div><div><p className="font-medium">{name}</p><p className="text-xs text-muted-foreground">{code} · {venue}</p></div></div><div className="text-left sm:text-right"><p className="font-mono text-sm text-primary">{day}</p><p className="text-xs text-muted-foreground">{time}</p></div></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Publish a class</CardTitle><CardDescription>Create a timetable entry for a course, level, and faculty.</CardDescription></CardHeader><CardContent className="flex flex-col gap-3"><Input placeholder="Course title" /><Input placeholder="Course code" /><div className="grid gap-3 sm:grid-cols-2"><Input placeholder="Day" /><Input placeholder="Start time" /></div><Input placeholder="Venue" /><Button className="rounded-xl" onClick={() => setSaved(true)}>{saved ? 'Class published' : 'Publish timetable entry'}</Button><p className="text-xs leading-5 text-muted-foreground">Lecturers can publish their own classes. Admins can review the complete university schedule.</p></CardContent></Card></div> : <div className="grid gap-6 lg:grid-cols-3"><Card className="lg:col-span-2"><CardHeader><CardTitle>{active === 'Interventions' ? 'Recommendation queue' : 'Cohort performance map'}</CardTitle><CardDescription>Updated from the latest authorized academic records.</CardDescription></CardHeader><CardContent className="flex flex-col gap-4">{['Attendance recovery plan', 'Assessment support session', 'Peer study group referral', 'Advisor check-in'].map((item, index) => <div key={item} className="flex items-center justify-between rounded-xl border border-border/70 p-4"><div><p className="font-medium">{item}</p><p className="text-xs text-muted-foreground">{index + 2} students · {index === 0 ? 'High priority' : 'Review recommended'}</p></div><Badge variant="outline" className="border-primary/20 text-primary">Review</Badge></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Recommendation method</CardTitle><CardDescription>How APAPPS supports decisions</CardDescription></CardHeader><CardContent className="flex flex-col gap-4"><Sparkles className="text-primary" /><p className="text-sm leading-6 text-muted-foreground">The AI layer is designed to summarize authorized academic aggregates, explain the drivers behind a recommendation, and suggest a next action. It never makes a final academic decision.</p><Badge variant="secondary" className="w-fit">AI-assisted · human reviewed</Badge></CardContent></Card></div>}</div>
}

function LecturerView({ active, userId }: { active: string; userId?: string }) {
  const supabase = createClient()
  const [profileSaved, setProfileSaved] = useState(false)
  const [profileName, setProfileName] = useState('')
  const [department, setDepartment] = useState('')
  async function saveLecturerProfile() { if (!supabase || !userId) return; const { error } = await supabase.from('profiles').update({ full_name: profileName, department }).eq('id', userId); setProfileSaved(!error) }
  const [selectedCourse, setSelectedCourse] = useState('CSC 305')
  if (active === 'Settings') return <div className="mx-auto flex max-w-6xl flex-col gap-6 p-5 lg:p-10"><section className="rounded-3xl border border-primary/15 bg-primary/5 p-6"><p className="text-xs uppercase tracking-[0.18em] text-primary">Lecturer profile</p><h2 className="mt-2 text-3xl font-semibold">Your teaching identity</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Keep your public teaching details current. Staff ID and verification status are controlled by administration.</p></section><Card><CardHeader><CardTitle>Profile details</CardTitle><CardDescription>Verified lecturer account · Staff ID: STAFF/2026/001</CardDescription></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><Input value={profileName} onChange={(e) => setProfileName(e.target.value)} placeholder="Full name" aria-label="Full name" /><Input defaultValue="Senior Lecturer" aria-label="Academic position" /><Input value={department} onChange={(e) => setDepartment(e.target.value)} placeholder="Department" aria-label="Department" /><Input defaultValue="Block B, Room 14" aria-label="Office location" /><Input defaultValue="Teaching and research interests" className="sm:col-span-2" aria-label="Professional bio" /><Button className="rounded-xl sm:col-span-2" onClick={saveLecturerProfile}>{profileSaved ? 'Profile saved' : 'Save profile changes'}</Button></CardContent></Card></div>
  if (active === 'My Cohort' || active === 'Students at Risk') return <div className="mx-auto flex max-w-6xl flex-col gap-6 p-5 lg:p-10"><section className="flex flex-col gap-3 rounded-3xl border border-primary/15 bg-primary/5 p-6"><p className="text-xs uppercase tracking-[0.18em] text-primary">Personalized lecturer workspace</p><h2 className="text-3xl font-semibold">Good morning, Dr. Osei.</h2><p className="max-w-2xl text-sm leading-6 text-muted-foreground">This view only includes students enrolled in your assigned courses. Use the signals to decide who needs a conversation, not to replace your academic judgement.</p></section><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={BookOpen} label="Assigned courses" value="4" detail="This semester" tone="primary" /><StatCard icon={Users} label="Enrolled students" value="128" detail="Across your courses" /><StatCard icon={AlertTriangle} label="Need a check-in" value="19" detail="7 high priority" tone="warning" /><StatCard icon={TrendingUp} label="Class average" value="74.8%" detail="↑ 6.2% this term" tone="success" /></section><section className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]"><Card><CardHeader><CardTitle>{active === 'Students at Risk' ? 'Students at risk' : 'My courses'}</CardTitle><CardDescription>{active === 'Students at Risk' ? 'Prioritized support queue from assigned courses' : 'Select a course to open its teaching workspace'}</CardDescription></CardHeader><CardContent className="flex flex-col gap-3">{['CSC 305 · Database Systems','CSC 301 · Algorithms','CSC 307 · Software Engineering','MTH 204 · Discrete Mathematics'].map((course) => <button key={course} onClick={() => setSelectedCourse(course.split(' · ')[0])} className={`flex items-center justify-between rounded-2xl border p-4 text-left transition-colors ${selectedCourse === course.split(' · ')[0] ? 'border-primary/40 bg-primary/5' : 'border-border/70 hover:bg-muted/40'}`}><div><p className="font-medium">{course}</p><p className="text-xs text-muted-foreground">32 enrolled · 8 assessments · 2 interventions</p></div><ChevronRight className="text-muted-foreground" /></button>)}</CardContent></Card><Card><CardHeader><CardTitle>Verification status</CardTitle><CardDescription>Access boundary</CardDescription></CardHeader><CardContent className="flex flex-col gap-4"><Badge variant="outline" className="w-fit border-success/20 bg-success/10 text-success">Verified lecturer</Badge><p className="text-sm leading-6 text-muted-foreground">You can view records for assigned courses, write teaching notes, create interventions, and publish course timetable entries. Institution-wide controls remain with administrators.</p><Separator /><p className="text-xs text-muted-foreground">Last reviewed by Academic Registry · 18 Aug 2026</p></CardContent></Card></section></div>
  return <div className="mx-auto flex max-w-6xl flex-col gap-6 p-5 lg:p-10"><section className="rounded-3xl border border-primary/15 bg-primary/5 p-6"><p className="text-xs uppercase tracking-[0.18em] text-primary">Teaching cockpit</p><h2 className="mt-2 text-3xl font-semibold">Your courses, your students, your next action.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">A focused workspace for teaching decisions: review course health, follow up with students, and track whether support is working.</p></section><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={BookOpen} label="Assigned courses" value="4" detail="First semester" tone="primary" /><StatCard icon={Users} label="Students" value="128" detail="Across assigned courses" /><StatCard icon={ShieldCheck} label="Verified access" value="Active" detail="Staff profile approved" tone="success" /><StatCard icon={MessageSquareText} label="Open interventions" value="12" detail="3 awaiting follow-up" tone="warning" /></section><section className="grid gap-6 lg:grid-cols-2"><Card><CardHeader><CardTitle>Course health</CardTitle><CardDescription>Average performance and support signals</CardDescription></CardHeader><CardContent className="flex flex-col gap-4">{[['CSC 305','74%',68],['CSC 301','82%',86],['CSC 307','78%',79],['MTH 204','66%',61]].map(([code,score,attendance]) => <div key={code as string} className="flex flex-col gap-2"><div className="flex justify-between text-sm"><span className="font-medium">{code}</span><span className="font-mono text-muted-foreground">{score}</span></div><Progress value={attendance as number} /><p className="text-xs text-muted-foreground">Attendance coverage {attendance}%</p></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Next teaching actions</CardTitle><CardDescription>Focused tasks for today</CardDescription></CardHeader><CardContent className="flex flex-col gap-3">{['Review 7 high-priority students','Publish CSC 305 assessment','Follow up on attendance plan','Update office hours'].map((task, index) => <div key={task} className="flex items-center gap-3 rounded-xl border border-border/70 p-3"><div className="flex size-8 items-center justify-center rounded-full bg-primary/10 text-primary">{index + 1}</div><p className="text-sm">{task}</p></div>)}</CardContent></Card></section></div>
}

function LiveStudentPanel({ title, description, loading, children }: { title: string; description: string; loading: boolean; children: React.ReactNode }) { return <div className="mx-auto flex max-w-6xl flex-col gap-6 p-5 lg:p-10"><section className="rounded-3xl border border-primary/15 bg-primary/5 p-6"><p className="text-xs uppercase tracking-[0.18em] text-primary">Student portal</p><h2 className="mt-2 text-3xl font-semibold">{title}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{description}</p></section><Card><CardContent className="flex flex-col gap-4 p-6">{loading ? <p className="text-sm text-muted-foreground">Loading your live data…</p> : children}</CardContent></Card></div> }

function StudentView({ active, userId }: { active: string; userId?: string }) {
  const supabase = createClient()
  const [records, setRecords] = useState<Array<{ id: string; course_code: string; attendance: number; classwork: number; assignments: number; examinations: number }>>([])
  const [notifications, setNotifications] = useState<Array<{ id: string; title: string; body: string; kind: string; read_at: string | null }>>([])
  const [loading, setLoading] = useState(true)
  const average = records.length ? Math.round(records.reduce((sum, record) => sum + Number(record.classwork || 0) + Number(record.assignments || 0) + Number(record.examinations || 0), 0) / (records.length * 3)) : null
  const attendanceAverage = records.length ? Math.round(records.reduce((sum, record) => sum + Number(record.attendance || 0), 0) / records.length) : null
  const risk = attendanceAverage === null || average === null ? 'Awaiting records' : average < 50 || attendanceAverage < 60 ? 'High risk' : average < 65 || attendanceAverage < 75 ? 'Needs attention' : 'On track'
  const [profileName, setProfileName] = useState('')
  const [profileMessage, setProfileMessage] = useState('')
  const [profilePhone, setProfilePhone] = useState('')
  const [profileAddress, setProfileAddress] = useState('')
  async function saveProfile() {
    if (!supabase || !userId || !profileName.trim()) return
    const { error } = await supabase.from('profiles').update({ full_name: profileName.trim(), phone: profilePhone.trim(), address: profileAddress.trim() }).eq('id', userId)
    setProfileMessage(error ? error.message : 'Profile updated successfully.')
  }
  async function uploadAvatar(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]
    if (!file || !userId || !['image/jpeg', 'image/png'].includes(file.type) || file.size > 5 * 1024 * 1024) { setProfileMessage('Choose a JPEG or PNG image under 5 MB.'); return }
    const form = new FormData(); form.append('file', file); form.append('userId', userId)
    const response = await fetch('/api/profile-photo/upload', { method: 'POST', body: form }); const result = await response.json()
    if (!response.ok) { setProfileMessage(result.error || 'Photo upload failed.'); return }
    await supabase?.from('profiles').update({ avatar_path: result.pathname }).eq('id', userId); setProfileMessage('Profile photo updated. Refreshing…'); window.location.reload()
  }
  async function markNotificationRead(id: string) {
    if (!supabase) return
    await supabase.from('notifications').update({ read_at: new Date().toISOString() }).eq('id', id).eq('user_id', userId)
    setNotifications((items) => items.map((item) => item.id === id ? { ...item, read_at: new Date().toISOString() } : item))
  }
  useEffect(() => { if (supabase && userId) supabase.from('profiles').select('full_name, phone, address').eq('id', userId).maybeSingle().then(({ data }) => { setProfileName(data?.full_name || ''); setProfilePhone(data?.phone || ''); setProfileAddress(data?.address || '') }) }, [supabase, userId])
  useEffect(() => {
    if (!supabase || !userId) { setLoading(false); return }
    Promise.all([
      supabase.from('academic_records').select('id, course_code, attendance, classwork, assignments, examinations').eq('student_id', userId).order('course_code'),
      supabase.from('notifications').select('id, title, body, kind, read_at').eq('user_id', userId).order('created_at', { ascending: false }).limit(20),
    ]).then(([recordResult, notificationResult]) => { setRecords(recordResult.data ?? []); setNotifications(notificationResult.data ?? []); setLoading(false) })
  }, [supabase, userId])
  if (active === 'Settings') return <LiveStudentPanel title="Profile settings" description="Update the name shown across your student workspace." loading={false}><Input value={profileName} onChange={(e) => setProfileName(e.target.value)} placeholder="Full name" aria-label="Full name" /><Input value={profilePhone} onChange={(e) => setProfilePhone(e.target.value)} placeholder="Contact number" aria-label="Contact number" /><Input value={profileAddress} onChange={(e) => setProfileAddress(e.target.value)} placeholder="Home address" aria-label="Home address" /><Input type="file" accept="image/jpeg,image/png" onChange={uploadAvatar} aria-label="Profile photo" /><p className="text-xs text-muted-foreground">JPEG or PNG only, maximum 5 MB.</p><Button onClick={saveProfile} className="w-fit rounded-xl">Save profile</Button>{profileMessage && <p className="text-sm text-muted-foreground">{profileMessage}</p>}</LiveStudentPanel>
  if (active === 'Notifications') return <LiveStudentPanel title="Notification center" description="Your classes, deadlines, interventions, approvals, and announcements." loading={loading}>{notifications.length === 0 ? <p className="text-sm text-muted-foreground">No notifications yet.</p> : notifications.map((item) => <button type="button" key={item.id} onClick={() => markNotificationRead(item.id)} className={`flex gap-3 rounded-2xl border p-4 text-left transition-colors ${item.read_at ? 'border-border/50 opacity-70' : 'border-primary/30 bg-primary/5'}`}><Bell className="mt-1 text-primary" /><div><p className="font-medium">{item.title}</p><p className="mt-1 text-sm leading-6 text-muted-foreground">{item.body}</p><Badge variant="outline" className="mt-2 capitalize">{item.kind}</Badge></div></button>)}</LiveStudentPanel>
  if (active === 'Overview') return <LiveStudentPanel title={`Welcome back, ${profileName.split(' ')[0] || 'Student'}`} description="Your overview is calculated from academic records saved to your account. No demo performance values are shown." loading={loading}><div className="grid gap-4 sm:grid-cols-3"><StatCard icon={TrendingUp} label="Average score" value={average === null ? '—' : `${average}%`} detail={records.length ? `${records.length} course records` : 'No records yet'} tone="primary" /><StatCard icon={CalendarDays} label="Attendance" value={attendanceAverage === null ? '—' : `${attendanceAverage}%`} detail="From recorded attendance" /><StatCard icon={AlertTriangle} label="Support signal" value={risk} detail="Assistive indicator, not a final decision" tone="warning" /></div>{records.length === 0 && <p className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground">Your lecturer or administrator has not entered academic records yet. Once attendance and assessments are recorded, this page will calculate your current support signal.</p>}</LiveStudentPanel>
  if (active === 'Academic records' || active === 'Analytics') return <LiveStudentPanel title={active === 'Analytics' ? 'My performance analytics' : 'Academic records'} description="These values are loaded from your confirmed Supabase profile and academic records." loading={loading}>{records.length === 0 ? <p className="text-sm text-muted-foreground">No academic records have been entered for your account yet.</p> : <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead><tr className="border-b text-left text-xs uppercase tracking-wider text-muted-foreground"><th className="pb-3">Course</th><th className="pb-3">Attendance</th><th className="pb-3">Classwork</th><th className="pb-3">Assignment</th><th className="pb-3">Exam</th></tr></thead><tbody>{records.map((record) => <tr key={record.id} className="border-b border-border/60"><td className="py-4 font-medium">{record.course_code}</td><td className="py-4">{record.attendance}%</td><td className="py-4">{record.classwork}%</td><td className="py-4">{record.assignments}%</td><td className="py-4">{record.examinations}%</td></tr>)}</tbody></table></div>}</LiveStudentPanel>
  const [whatIf, setWhatIf] = useState(false)
  const [goalAdded, setGoalAdded] = useState(false)
  return <div className="mx-auto flex max-w-6xl flex-col gap-6 p-5 lg:p-10"><section className="flex flex-col gap-5 rounded-3xl border border-primary/15 bg-primary/5 p-6 lg:flex-row lg:items-end lg:justify-between lg:p-8"><div className="flex max-w-3xl flex-col gap-3"><div className="flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-primary"><GraduationCap /> Student success plan</div><h2 className="text-pretty text-3xl font-semibold tracking-tight lg:text-5xl">Your academic story, explained clearly.</h2><p className="text-sm leading-6 text-muted-foreground lg:text-base">APAPPS combines your attendance, assessments, classwork, examinations, timetable, and goals to help you act before a small setback becomes a serious one.</p></div><Badge variant="outline" className="w-fit border-success/20 bg-success/10 text-success">Low risk · 84% success probability</Badge></section><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={TrendingUp} label="Success probability" value="84%" detail="↑ 7% from last review" tone="primary" /><StatCard icon={ShieldCheck} label="Risk level" value="Low" detail="No urgent signals" tone="accent" /><StatCard icon={BookOpen} label="Current GPA" value="3.72" detail="Target: 4.00" tone="teal" /><StatCard icon={CheckCircle2} label="Attendance" value="92%" detail="Above course average" tone="success" /></section><section className="grid gap-6 lg:grid-cols-[1.3fr_0.7fr]"><Card><CardHeader><div className="flex items-start justify-between gap-4"><div><CardTitle>Why this prediction?</CardTitle><CardDescription>Last updated from your authorized academic records</CardDescription></div><Badge variant="secondary">Explainable</Badge></div></CardHeader><CardContent className="flex flex-col gap-5"><div className="grid gap-4 sm:grid-cols-3"><div className="rounded-2xl border border-success/20 bg-success/5 p-4"><p className="text-xs text-muted-foreground">Positive signal</p><p className="mt-2 font-medium">Attendance consistency</p><p className="mt-1 text-sm text-success">92% · +12 pts</p></div><div className="rounded-2xl border border-warning/20 bg-warning/5 p-4"><p className="text-xs text-muted-foreground">Watch signal</p><p className="mt-2 font-medium">CSC 305 exams</p><p className="mt-1 text-sm text-warning">68% · needs practice</p></div><div className="rounded-2xl border border-primary/20 bg-primary/5 p-4"><p className="text-xs text-muted-foreground">Momentum</p><p className="mt-2 font-medium">Improving weekly</p><p className="mt-1 text-sm text-primary">+7% this term</p></div></div><p className="text-sm leading-6 text-muted-foreground">This is an assistive estimate, not a verdict. Your lecturer or advisor should review the evidence with you before any intervention is assigned.</p></CardContent></Card><Card><CardHeader><CardTitle>Next best actions</CardTitle><CardDescription>Small steps with measurable impact</CardDescription></CardHeader><CardContent className="flex flex-col gap-3"><Button className="justify-between rounded-xl" onClick={() => setGoalAdded(true)}>Set a weekly study goal <Target data-icon="inline-end" /></Button><Button variant="outline" className="justify-between rounded-xl" onClick={() => setWhatIf((value) => !value)}>Try a What-If scenario <ArrowUpRight data-icon="inline-end" /></Button>{goalAdded && <Badge variant="outline" className="border-success/20 bg-success/10 text-success">Goal saved: 4 focused study blocks</Badge>}{whatIf && <div className="rounded-2xl border border-border/70 bg-muted/40 p-4"><p className="font-medium">If attendance reaches 96%</p><p className="mt-1 text-sm leading-6 text-muted-foreground">Estimated success probability could rise to 88%, assuming your assessment momentum stays steady.</p><Progress value={88} className="mt-3" /></div>}</CardContent></Card></section><section className="grid gap-6 lg:grid-cols-3"><Card className="lg:col-span-2"><CardHeader><CardTitle>Course risk signals</CardTitle><CardDescription>See where support could make the biggest difference</CardDescription></CardHeader><CardContent className="flex flex-col gap-3">{[['CSC 305 · Database Systems','74%','Stable'],['MTH 204 · Discrete Mathematics','66%','Watch'],['CSC 301 · Algorithms','88%','Strong']].map(([course,score,status]) => <div key={course} className="flex items-center justify-between rounded-2xl border border-border/70 p-4"><div><p className="font-medium">{course}</p><p className="text-xs text-muted-foreground">Predicted course success</p></div><div className="text-right"><p className="font-mono text-lg">{score}</p><Badge variant="outline" className={status === 'Watch' ? 'border-warning/20 text-warning' : 'border-success/20 text-success'}>{status}</Badge></div></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Today</CardTitle><CardDescription>Stay oriented</CardDescription></CardHeader><CardContent className="flex flex-col gap-4"><div className="flex gap-3"><CalendarDays className="text-primary" /><div><p className="font-medium">CSC 305 · 10:00</p><p className="text-xs text-muted-foreground">Database Lab · Lab 1</p></div></div><Separator /><div className="flex gap-3"><Bell className="text-warning" /><div><p className="font-medium">Assignment due Friday</p><p className="text-xs text-muted-foreground">Algorithms problem set</p></div></div><Separator /><p className="text-xs leading-5 text-muted-foreground">Need help? Message your advisor from the support channel in your workspace.</p></CardContent></Card></section></div>
}

function LegacyStudentView() {
  return <div className="mx-auto flex max-w-5xl flex-col gap-8 p-5 lg:p-10"><section className="rounded-3xl border border-primary/15 bg-gradient-to-br from-primary/10 via-card to-card p-6 lg:p-8"><div className="flex max-w-2xl flex-col gap-3"><div className="flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-primary"><GraduationCap /> Your learning snapshot</div><h2 className="text-pretty text-3xl font-semibold tracking-tight lg:text-5xl">You are building strong momentum.</h2><p className="text-sm leading-6 text-muted-foreground lg:text-base">Your latest signals point to a healthy academic trajectory. Keep showing up and use the next steps below to stay on track.</p></div></section><section className="grid gap-4 sm:grid-cols-3"><StatCard icon={TrendingUp} label="Overall average" value="86%" detail="↑ 4.8% from last month" tone="primary" /><StatCard icon={CheckCircle2} label="Attendance" value="92%" detail="Excellent consistency" tone="teal" /><StatCard icon={ShieldCheck} label="Predicted risk" value="Low" detail="You are on track" tone="accent" /></section><section className="grid gap-6 lg:grid-cols-[1.3fr_0.7fr]"><Card><CardHeader><CardTitle>Your performance trend</CardTitle><CardDescription>Assessment average across the semester</CardDescription></CardHeader><CardContent><div className="h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData}><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="4 4" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><YAxis domain={[50, 100]} axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><Area type="monotone" dataKey="score" stroke="var(--chart-1)" fill="var(--chart-1)" fillOpacity={0.12} strokeWidth={3} /></AreaChart></ResponsiveContainer></div></CardContent></Card><Card><CardHeader><CardTitle>Suggested next steps</CardTitle><CardDescription>Personalized for your current progress</CardDescription></CardHeader><CardContent className="flex flex-col gap-4">{['Keep your attendance above 85%', 'Review the next CA study guide', 'Book a feedback session'].map((item) => <div key={item} className="flex items-center gap-3 rounded-xl bg-muted/60 p-3 text-sm"><CheckCircle2 className="text-success" />{item}</div>)}</CardContent></Card></section></div>
}

function _UnusedChart({ data }: { data: { name: string; performance: number }[] }) {
  return <BarChart data={data}><Bar dataKey="performance" /></BarChart>
}
